// MARK: canonical lines (mirror gen2.py state() / run())

func f3(_ x: Double) -> String { let s = String(format: "%.3f", x); return s == "-0.000" ? "0.000" : s }
func pyList(_ xs: [String]) -> String { "[" + xs.joined(separator: ", ") + "]" }
func opt(_ s: String?) -> String { s ?? "None" }

func stateLines(_ s: GameSession) -> [String] {
    let w = s.world, vm = s.vm
    var L = ["world \(w.level) \(opt(w.currentCamera)) \(w.scriptAuto ? 1 : 0) \(opt(w.playerName)) \(vm.tick) \(vm.nextHandle)"]
    for k in w.figures.keys {
        let f = w.figures[k]!
        let pos = f.pos.map { [$0.x, $0.y, $0.z].map(f3).joined(separator: ",") } ?? "None"
        let hp = pyStr(vm.objectRecord(w.objectKey(k))[0])
        L.append("fig \(k) \(f.type) \(pos) \(f3(f.heading)) \(opt(f.motion)) \(f.combat ? 1 : 0) \(hp) \(opt(f.enemy)) \(opt(f.aiType)) "
                 + "\(f.aiProc.map { String($0.handle) } ?? "-") \(f.viewCams.map { $0.joined(separator: ",") } ?? "-")")
    }
    for k in w.items.keys {
        let i = w.items[k]!
        L.append("item \(k) \(i.name) \(i.type) \(opt(i.owner)) \(opt(i.slot)) \(vm.objects[k].map { pyRepr(.list($0)) } ?? "None")")
    }
    for p in vm.processes {
        L.append("proc \(p.handle) \(p.block.name) \(p.block.kind) \(p.pc) \(p.wake) \(p.waitOn.map { String($0.handle) } ?? "-") \(opt(p.curFig)) "
                 + "\(opt(p.curItem)) \(p.suspended ? 1 : 0) \(pyRepr(.list(p.locals))) \(p.origin.map(String.init) ?? "None") \(p.pending.count) "
                 + "\(pyList(p.waiters.map { String($0.handle) })) \(p.owner)")
    }
    L.append("globals " + sha256(vm.globals.keys.sorted().map { "\($0)=\(pyRepr(vm.globals[$0]!))" }.joined(separator: "\n")))
    return L
}

func runLines(_ s: GameSession) -> [String] {
    let w = s.world, vm = s.vm
    var L = ["log \(w.log.count) " + sha256(w.log.map { "\($0.tick)|\($0.block)|\($0.kind.rawValue)|\($0.name)|\(pyRepr(.list($0.args)))" }.joined(separator: "\n"))]
    L.append("camera_changes " + pyList(w.cameraChanges.map { "(\($0.tick), \($0.from.map(pyRepr) ?? "None"), \(pyRepr($0.to)), \(pyRepr($0.reason)))" }))
    L.append("changes \(vm.changes.count) " + sha256(vm.changes.map { "(\($0.tick), \(pyRepr($0.name)), \(pyRepr($0.old)), \(pyRepr($0.new)))" }.joined(separator: "\n")))
    L.append("warnings " + pyList((w.warnings + vm.warnings).map { pyRepr($0) }))
    L.append("events " + pyList(w.events.map { "(\($0.tick), \(pyRepr($0.block)))" }))
    L.append("level_loads " + pyList(w.levelLoads.map { "(\($0.tick), \(pyRepr($0.level)), \($0.arrival.map(pyRepr) ?? "None"))" }))
    L.append("sound_log \(w.soundLog.count) music_log \(w.musicLog.count)")
    return L
}

func digest(_ lines: [String]) -> (count: Int, sha: String) { (lines.count, sha256(lines.joined(separator: "\n"))) }

func check(_ s: GameSession, start: (count: Int, sha: String), after300: (count: Int, sha: String), _ label: String) {
    let l0 = stateLines(s)
    if digest(l0) != start { Issue.record("\(label): resumed state differs from Python\n\(l0.joined(separator: "\n"))") }
    for _ in 0..<300 { s.autoDifficulty = false; s.tick() }
    let l1 = stateLines(s) + runLines(s)
    if digest(l1) != after300 { Issue.record("\(label): state after 300 ticks differs from Python\n\(l1.joined(separator: "\n"))") }
}

@Suite(.enabled(if: game != nil, "BIOFORGE_DATA is not set; point it at the BioForge game folder"))
struct SaveLoadTests {
    @Test func resumeRestoresBouncyFlag() throws {
        let g = try requireGame(), res = try #require(worldResources)
        let directory = try #require(g.gamedat)
        var state = try SaveState.load(directory: directory)
        var level = try #require(state.levels["CHAOS"])
        let index = try #require(level.chunks.firstIndex { $0.id == "PLAY" })
        level.chunks[index].data[21] |= UInt8(ObjRec.flagBouncy)
        state.levels["CHAOS"] = level
        let session = try GameSession(resources: res, level: "CHAOS", stateDirectory: directory)
        _ = try session.restore(state)
        #expect(session.world.player?.bouncy == true)
    }

    @Test func gamedatResumesLikePython() throws {
        let g = try requireGame(), res = try #require(worldResources)
        let s = try GameSession.fromNativeState(resources: res, directory: try #require(g.gamedat))
        #expect(s.world.camera != nil && s.world.camera == s.world.loadedCam)   // the restore's switch makes the saved camera current (1130:0114)
        #expect(s.world.resumed.count == 12 && s.world.currentCamera == gamedatResume.camera)
        #expect(s.world.warnings + s.vm.warnings == [])
        check(s, start: gamedatResume.start, after300: gamedatResume.after300, "GAMEDAT")
    }

    @Test func nativeSampleResumesLikePython() throws {
        let res = try #require(worldResources)
        guard FileManager.default.fileExists(atPath: nativeSample.path) else { return }
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        try Im1.unpack(try fileBytes(nativeSample), to: dir)
        let s = try GameSession.fromNativeState(resources: res, directory: dir)
        #expect(s.world.currentCamera == nativeResume.camera)
        #expect(s.world.warnings + s.vm.warnings == [])
        check(s, start: nativeResume.start, after300: nativeResume.after300, "GAME1.IM1")
    }

    @Test func resumedHandlesAndWaitState() throws {
        let g = try requireGame(), res = try #require(worldResources)
        let s = try GameSession.fromNativeState(resources: res, directory: try #require(g.gamedat))
        let vm = s.vm
        #expect(vm.process(2218)?.wake == 1696 && vm.process(24)?.wake == 5 && vm.process(31)?.wake == 5430)
        #expect(vm.process(838)?.waitOn === vm.process(2218))
        #expect(vm.process(2211)?.block.name == "MODIFYVAREVERYNTH" && vm.nextHandle >= 2305)
        guard case .int(let h)? = vm.globals["_cellone" + "process"] else { Issue.record("no handle"); return }
        #expect(vm.process(h)?.block.name == "CELLONEBARS")
        // the blocked CALL continues when the child ends
        let parent = try #require(vm.process(838)), at = parent.pc
        vm.finish(try #require(vm.process(2218)))                   // only wakes the caller (1238:077f) ...
        #expect(parent.waitOn == nil && parent.pc == at)
        vm.tickOnce()                                               // ... the next walk re-enters the CALL statement, which completes
        #expect(parent.pc != at)
        #expect(s.world.warnings + vm.warnings == [])
    }

    // MARK: re/interp/test_save.py

    private func session(_ g: GameFolder, state: URL?, savesDir: URL) throws -> (GameSession, String) {
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS", stateDirectory: state)
        s.world.savesDir = savesDir
        s.world.setCamera("CE11", "test")
        let key = try #require(try defaultVars(g).first?.name.lowercased())
        s.vm.globals[key] = .int(4321)
        return (s, key)
    }

    private func liveBlocks(_ vm: ScriptVM) -> [String] { vm.processes.filter { !$0.done && $0.block.kind != "native" }.map(\.block.name).sorted() }

    private func checkContainer(_ url: URL) throws {
        let (ents, thumb, _) = try Im1.entries(try fileBytes(url))
        #expect(ents.map(\.name) == (["MISC.DAT", "SCRIPT.DAT", "LISTS.FLX", "VARS.DEF", "SOUNDS.DEF"] +
                                      ["BEACH", "CHAOS", "CONTROL", "DIGSITE", "LANDPAD", "PLATFORM", "TANKS", "TITLE", "TOWER", "TUNROOM"].map { $0 + ".IFF" }).sorted())
        let f = try CAMImage.decodeFrame(thumb, at: 0)
        #expect((f.width, f.height, f.hotX, f.hotY) == (320, 200, 0, 0) && f.mask.allSatisfy { $0 == 1 })
        #expect(f.pixels.allSatisfy { $0 >= 128 && $0 < 160 })
    }

    @Test func saveFromNativeStateAndLoadItBack() throws {
        let g = try requireGame(), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let (s, key) = try session(g, state: try #require(g.gamedat), savesDir: dir)
        let path = try #require(s.world.saveNative(slot: 3))
        #expect(path.lastPathComponent == "GAME3.IM1")
        try checkContainer(path)
        let loaded = try #require(s.world.loadNative(slot: 3))
        #expect(loaded.world.level == "CHAOS" && loaded.world.currentCamera == "CE11" && loaded.vm.globals[key] == .int(4321))
        #expect(s.world.pendingLoad === loaded)
        let st = try SaveState.load(directory: dir.appendingPathComponent("GAME3.d"))
        #expect([st.misc.saveName, st.misc.level, st.misc.camera] == ["GAME3.IM1", "CHAOS.IFF", "CE11"])
        let shipped = try SaveState.load(directory: try #require(g.gamedat)).script
        func system(_ sd: ScriptDat) -> [String] { sd.slots.filter { $0.index < 6 }.map { "\($0.index) \($0.vtable) \(sha($0.b))" } }
        #expect(system(st.script) == system(shipped))         // the system slots are kept
        #expect(liveBlocks(loaded.vm) == liveBlocks(s.vm))           // the world's processes are written and resumed
    }

    @Test func aFailedSaveOrLoadIsReportedOnce() throws {
        let g = try requireGame(), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let (s, _) = try session(g, state: try #require(g.gamedat), savesDir: dir)
        #expect(s.world.loadNative(slot: 5) == nil)                                  // an empty slot
        let load = try #require(s.world.takeFileError())
        #expect(load.load && load.slot == 5)
        #expect(s.world.takeFileError() == nil)                                      // taken once
        try Data("not a save".utf8).write(to: dir.appendingPathComponent("GAME6.IM1"))
        #expect(s.world.loadNative(slot: 6) == nil)                                  // an unreadable slot
        #expect(s.world.takeFileError()?.slot == 6)
        try FileManager.default.createDirectory(at: dir.appendingPathComponent("GAME7.IM1"), withIntermediateDirectories: true)
        #expect(s.world.saveNative(slot: 7) == nil)                                  // a folder where the file goes: the write fails
        let save = try #require(s.world.takeFileError())
        #expect(!save.load && save.slot == 7)
        #expect(s.world.saveNative(slot: 3) != nil && s.world.takeFileError() == nil)
    }

