    /// test_save.py `test_the_player_and_figure_state_come_back`: a new game's level file has no PLAY record, the writer appends one.
    @Test func thePlayerAndFigureStateComeBack() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let w = s.world
        w.savesDir = dir
        let block = ScriptBlock("TEST", "routine", 0, nil)
        _ = w.call(.stmt, "CREATEFIGURE", [.str("LEX"), .str("LEX"), .str("PLAYER")], ScriptProcess(vm: s.vm, handle: 0, block: block, code: s.vm.code(block), ctx: ScriptContext(curFig: nil)))
        let lex = try #require(w.player)
        lex.pos = V3(-10944, -7281, -5754)
        lex.heading = 30
        s.vm.setObject(w.objectKey("LEX"), [77, 0, 0, 0, 0, 0, 0, 0, 0, 0].map { .int($0) })
        let name = try #require(w.data.objs.first { $0.tag == "FIGR" }?.raw.cString(33, 42).uppercased())
        let fig = try #require(w.figure(name))
        fig.heading = -45; fig.combat = true; fig.hold = 1; fig.enemy = "PLAYER"
        #expect(fig.setMotion("ATK_STAND", loop: true))
        s.vm.setObject(w.objectKey(name), (0..<10).map { i -> ScriptValue in .int(i == 0 ? 33 : i) })
        _ = try #require(w.saveNative(slot: 1))
        let w2 = try #require(w.loadNative(slot: 1)).world
        let lex2 = try #require(w2.player), fig2 = try #require(w2.figures[name])
        #expect(w2.playerName == "LEX" && [lex2.pos!.x, lex2.pos!.y].map { Int($0.rounded()) } == [-10944, -7281] && Int(lex2.heading.rounded()) == 30)
        #expect(w2.vm?.objectRecord("LEX")[0] == .int(77))
        #expect(Int(fig2.heading.rounded()) == -45 && fig2.combat && fig2.hold == 1 && fig2.enemy == "PLAYER" && fig2.motion == "ATK_STAND")
        #expect(w2.vm?.objectRecord(name) == (0..<10).map { i -> ScriptValue in .int(i == 0 ? 33 : i) })
        #expect([fig2.pos!.x, fig2.pos!.y, fig2.pos!.z].map { Int($0.rounded()) } == [fig.pos!.x, fig.pos!.y, fig.pos!.z].map { Int($0.rounded()) })
    }

    // MARK: processes, records and the other state a save carries (re/NOTES.md "Save state")

    private func caller(_ s: GameSession) -> ScriptProcess {
        let block = ScriptBlock("TEST", "routine", 0, nil)
        return ScriptProcess(vm: s.vm, handle: 0, block: block, code: s.vm.code(block), ctx: ScriptContext(curFig: nil))
    }

    /// Saves slot 1 of `s`, unpacks it and loads it back: the loaded session and the saved play directory's state.
    private func roundTrip(_ s: GameSession, _ dir: URL) throws -> (GameSession, SaveState) {
        s.world.savesDir = dir
        _ = try #require(s.world.saveNative(slot: 1))
        let loaded = try #require(s.world.loadNative(slot: 1))
        return (loaded, try SaveState.load(directory: dir.appendingPathComponent("GAME1.d")))
    }

    private func records(_ st: SaveState, _ tag: String) throws -> [ObjRec] {
        try #require(st.levels["CHAOS"]).records().compactMap { $0.object.tag == tag ? $0.rec : nil }
    }

    @Test func processesAreWrittenAndResumed() throws {
        let g = try requireGame(), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession.fromNativeState(resources: try #require(worldResources), directory: try #require(g.gamedat))
        let (loaded, st) = try roundTrip(s, dir)
        let live = liveBlocks(s.vm)
        #expect(live.count >= 12 && liveBlocks(loaded.vm) == live)
        #expect(st.script.slots.filter { $0.kind == .proc }.count == live.count)
        #expect(loaded.vm.process(838)?.waitOn === loaded.vm.process(2218))           // a blocked CALL and its child come back linked
        #expect(loaded.vm.process(2218)?.wake == s.vm.process(2218)?.wake)
        #expect(loaded.world.warnings + loaded.vm.warnings == [])
    }

    /// The difficulty is the `_difficulty_level` variable, which a save keeps; a load copies it back to [a36e] (FUN_1148_0490).
    @Test func hardStaysHardAfterALoad() throws {
