    /// The writer puts the items in the world's order and the reader makes them in record order (FUN_1148_0d46), so a floor item that came
    /// after Lex's items (a level entered with them) still comes after them, and the inventory lists it last once picked up.
    @Test func theItemListOrderComesBack() throws {
        let g = try requireGame(), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession.fromNativeState(resources: try #require(worldResources), directory: try #require(g.gamedat))
        let carried = s.world.items.keys.filter { s.world.items[$0]!.owner == "LEX" }
        var reordered = OrderedMap<Item>()
        for k in carried + s.world.items.keys.filter({ !carried.contains($0) }) { reordered[k] = s.world.items[k] }
        s.world.items = reordered                                                    // as after a level change
        let (loaded, _) = try roundTrip(s, dir)
        #expect(loaded.world.items.keys == s.world.items.keys)
        let fork = try #require(loaded.world.items["FORK"])
        fork.owner = "LEX"; fork.slot = "INVENTORY"; fork.pos = nil
        #expect(loaded.world.inventoryItems().map(\.key) == carried + ["FORK"])
    }

    @Test func aTimedHandleSurvivesASaveWithItsTicksLeft() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let h = s.vm.timedHandle(ticks: 50)
        for _ in 0..<10 { s.tick() }
        let left = try #require(s.vm.process(h)).wake - s.vm.tick
        #expect(left > 0 && left <= 50)
        let (loaded, st) = try roundTrip(s, dir)
        let task = try #require(st.script.slots.first { $0.serial == h })
        let (ticks, owner) = (try task.a.u16(0x40), try task.task().owner)
        #expect(task.vtable == 0x6677 && ticks == left && owner == 0)       // a Wait task with no owner
        let p = try #require(loaded.vm.process(h))
        #expect(p.block.name == "TIMED" && !p.done && p.wake - loaded.vm.tick == left)
    }

