    @Test func scriptMadeFiguresAndItemsGetRecords() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let w = s.world, c = caller(s)
        _ = w.call(.stmt, "CREATEFIGURE", [.str("LEX"), .str("LEX"), .str("PLAYER")], c)
        let kind = try #require(w.data.objs.first { $0.tag == "FIGR" }?.raw.cString(0, 9).uppercased())
        _ = w.call(.stmt, "CREATEFIGURE", [.str(kind), .str("ZED")], c)
        let zed = try #require(w.figures["ZED"]), lex = try #require(w.player)
        lex.pos = V3(1000, 2000, 3000); zed.pos = V3(100, 200, 300)
        _ = w.call(.stmt, "CREATEITEM", [.str("FORK")], c)
        let forkKey = try #require(c.curItem)
        let fork = try #require(w.items[forkKey])
        fork.owner = "LEX"; fork.slot = "INVENTORY"
        s.vm.setObject(fork.key, [7, 6, 5, 0, 0, 0, 0, 0, 0, 0].map { .int($0) })
        let (loaded, st) = try roundTrip(s, dir)
        let figs = try records(st, "FIGR"), play = try records(st, "PLAY")
        let zedRec = try #require(figs.first { $0.inst == "ZED" })
        #expect(zedRec.name == kind && zedRec.pos == [100, 200, 300] && play.map(\.inst) == ["LEX"])
        let items = try records(st, "ITEM")
        let forkRec = try #require(items.first { $0.inst == forkKey })
        let objects = try #require(st.levels["CHAOS"]).objects()
        let playId = try #require(objects.firstIndex { $0.tag == "PLAY" }) + 1
        #expect(forkRec.name == "FORK" && forkKey != "FORK" && forkRec.holder == playId && Array(forkRec.locals[0...2]) == [7, 6, 5])
        #expect(objects.last?.tag == "ITEM")                    // the items follow the other records
        let zed2 = try #require(loaded.world.figures["ZED"])
        #expect([zed2.pos!.x, zed2.pos!.y].map { Int($0.rounded()) } == [100, 200])
        let fork2 = try #require(loaded.world.items[forkKey])
        #expect(fork2.owner == "LEX" && fork2.slot == "INVENTORY" && loaded.vm.objectRecord(forkKey)[0] == .int(7))
    }

    /// The original saves a missile task (vtable 0x47a9; FUN_10e0_135a writes the owner's and the item's ids after the task lists,
    /// FUN_10e0_12b7 reads them back) and its item as an ITEM record: the shot flies on after a load, under the same handle, from the
    /// same position, orientation, velocity, range and spin, and the two worlds move it the same way (test_save.py).
    @Test func aMissileInFlightComesBack() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let w = s.world
        let fig = try #require(w.figures["CAYNAN"])                 // above Caynan in his cell: a slow shot stays clear of the walls
        let rows = [[0, 0, 256], [181, 181, 0], [181, -181, 0]]
        let at = fig.pos! + V3(0, 0, 1500)
        let m = w.spawnMissile("LASER", [Int(at.x), Int(at.y), Int(at.z)], rows, 4 * 2048, 30000, [0, 0, 7], owner: fig)
        for _ in 0..<2 { s.tick() }
        #expect(!m.dead)
        let (loaded, st) = try roundTrip(s, dir)
        let slot = try #require(st.script.slots.first { $0.vtable == 0x47a9 })
        #expect(slot.serial == m.handle && slot.a.count == 0x56 && slot.type == 0x10c)
        let m2 = try #require(loaded.world.items.values.compactMap { $0 as? Missile }.first)
        #expect(m2.key == m.key && m2.type == "LASER" && m2.handle == m.handle && m2.dist == m.dist && m2.spin == [0, 0, 7])
        #expect(m2.ownerFig?.name == "CAYNAN")
        #expect(ipos(m2) == ipos(m) && m2.rows == m.rows && m2.vel == m.vel)
        #expect(loaded.vm.procs[m2.handle] != nil)
        for _ in 0..<3 { s.tick(); loaded.tick() }
        #expect(!m.dead)
        #expect(ipos(m2) == ipos(m) && m2.dist == m.dist && !m2.dead)
        #expect(loaded.world.warnings + loaded.vm.warnings == [])
    }

    /// SUSPENDWHILE MODIFYVAREVERYNTH: a load links the waiter to its ramp again, so the CHAOS drip stays in step with the unsaved game.
    @Test func aProcessWaitingOnARampWaitsAgain() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        s.world.setCamera("BLK1", "test")                           // the drip's LINKMETOCAMERAS: elsewhere it is suspended
        s.vm.spawn("BLOCK_DRIP")
        func drip(_ g: GameSession) -> ScriptProcess? { g.vm.procs.values.first { $0.block.name.uppercased() == "BLOCK_DRIP" } }
        for _ in 0..<31 { s.tick() }                                // WAIT 30, then the first ramp of _dp1_frame
        let ramp = try #require(drip(s)?.waitOn)
        #expect(ramp.block.name == "MODIFYVAREVERYNTH")
        let (loaded, _) = try roundTrip(s, dir)
        #expect(drip(loaded)?.waitOn === loaded.vm.procs[ramp.handle])
        var pastRamp = false
        for k in 0..<120 {
            s.tick(); loaded.tick()
            let a = try #require(drip(s)), b = try #require(drip(loaded))
            pastRamp = pastRamp || a.waitOn !== ramp
            #expect(b.pc == a.pc && loaded.vm.globals["_dp1_frame"] == s.vm.globals["_dp1_frame"]
                    && loaded.vm.globals["_dp2_frame"] == s.vm.globals["_dp2_frame"], "tick \(k)")
        }
        #expect(s.vm.globals["_dp1_frame"] != nil && pastRamp)          // the drip got past its first ramp
    }

    private func ipos(_ m: Missile) -> [Int] { [m.pos!.x, m.pos!.y, m.pos!.z].map { Int($0) } }

    @Test func aiNameViewCamsAndVelocityRoundTrip() throws {
        let dir = tempDir()
