    /// Teeter, z cap, a foot override, the avoid list, invulnerable and the CAPTUREKEYBOARD hook come back (test_save.py's twin).
    @Test func aPausedProcessStaysPaused() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let g = try requireGame()
        let s = try GameSession.fromNativeState(resources: try #require(worldResources), directory: try #require(g.gamedat))
        let running = s.vm.processes.filter { $0.block.kind != "native" && !$0.suspended && $0.cameras.isEmpty }.map(\.handle)     // a camera link overrides the bit on load
        s.vm.processes.first { $0.handle == running[0] }!.suspended = true
        let (loaded, _) = try roundTrip(s, dir)
        #expect(loaded.vm.processes.first { $0.handle == running[0] }?.suspended == true)
        #expect(loaded.vm.processes.first { $0.handle == running[1] }?.suspended == false)
    }

    @Test func lostFigureStateRoundTrips() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let w = s.world
        let block = ScriptBlock("TEST", "routine", 0, nil)
        _ = w.call(.stmt, "CREATEFIGURE", [.str("LEX"), .str("LEX"), .str("PLAYER")], ScriptProcess(vm: s.vm, handle: 0, block: block, code: s.vm.code(block), ctx: ScriptContext(curFig: nil)))
        try #require(w.player).pos = V3(-10944, -7281, -5754)
        let name = try #require(w.data.objs.first { $0.tag == "FIGR" }?.raw.cString(33, 42).uppercased())
        let fig = try #require(w.figure(name))
        let wp = try #require(w.data.objs.first { $0.tag == "FIGR" && $0.raw.cString(33, 42).uppercased() != name }?.raw.cString(33, 42).uppercased())
        fig.teeter = true; fig.zCap = -321; fig.footOverride = fig.assets.footOffset + 17; fig.invulnerable = true
        fig.avoid = [(wp, 250), ("NOSUCHOBJECT", 9)]
        let hookBlock = try #require(s.vm.blocks.values.sorted { $0.name < $1.name }.first { b in
            guard b.defid != nil, let f = b.file, f.source != nil else { return false }
            return f.positions().contains { $0.block === b }
        })
        let hook = hookBlock.name.uppercased()
        w.keyboardCaptured = true; w.show.keyHook = hook
        let (loaded, st) = try roundTrip(s, dir)
        let rec = try #require(try records(st, "FIGR").first { $0.inst.uppercased() == name })
        let foot = fig.assets.footOffset + 17
        #expect(rec.teeter && rec.zCap == -321 && rec.foot == foot && rec.avoid.map(\.radius) == [250])
        #expect(try #require(try records(st, "PLAY").first).hookTask != 0)
        let f2 = try #require(loaded.world.figures[name])
        #expect(f2.teeter && f2.zCap == -321 && f2.footOverride == foot && f2.invulnerable)
        #expect(f2.avoid.map(\.name) == [wp] && f2.avoid.map(\.radius) == [250])
        #expect(loaded.world.keyboardCaptured && loaded.world.show.keyHook == hook && loaded.world.show.keyHookOwner == "level")
    }

    /// MOTION ... CONTINUE keeps a motion task, which the original's load restarts from the first frame (FUN_1088_4d67): the save writes
    /// it as a 0x46f5 task linked from the figure record (+0x13d); the phase is not kept (test_save.py's twin).
    @Test func aRunningContinueMotionRestartsFromFrame0() throws {
        let dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession(resources: try #require(worldResources), level: "CHAOS")
        let name = try #require(s.world.data.objs.first { $0.tag == "FIGR" }?.raw.cString(33, 42).uppercased())
        let fig = try #require(s.world.figure(name))
        let p = caller(s)
        let motion = try #require(fig.assets.assets.motions.first { m in
            guard m.frames.count > 4 else { return false }
            s.world.cmdMotion(fig, m.name, ["CONTINUE"], p)
            return fig.motion == m.name && !fig.loop
        }?.name)
        fig.idx = 3
        let (loaded, st) = try roundTrip(s, dir)
        let rec = try #require(try records(st, "FIGR").first { $0.inst.uppercased() == name })
        let slot = try #require(st.script.slots.first { $0.vtable == 0x46f5 })
        #expect(rec.motionTask == slot.index)
        #expect(String(decoding: slot.a[0x32..<0x4b].prefix { $0 != 0 }, as: UTF8.self).uppercased() == motion)
        let f2 = try #require(loaded.world.figures[name])
        #expect(f2.motion == motion && !f2.loop && f2.idx == 0 && f2.taskName == motion && f2.unwaited)
    }

    @Test func inventoryOrderSurvivesASave() throws {
        let g = try requireGame(), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession.fromNativeState(resources: try #require(worldResources), directory: try #require(g.gamedat))
        let w = s.world, c = caller(s)
        for type in ["FORK", "BLASTER"] {                                  // two script-made items, created after the level's own
            _ = w.call(.stmt, "CREATEITEM", [.str(type)], c)
            let key = try #require(c.curItem)
            let it = try #require(w.items[key])
            it.owner = w.playerName; it.slot = "INVENTORY"
        }
        func inventory(_ w: World) -> [String] { w.items.keys.filter { w.items[$0]?.owner == w.playerName && w.items[$0]?.slot == "INVENTORY" } }
        let before = inventory(w)
        #expect(before.count >= 5)
        let (loaded, _) = try roundTrip(s, dir)
        #expect(inventory(loaded.world) == before)
    }

