    @Test func newGameSaveIsByteIdenticalToPython() throws {
        let res = try #require(worldResources), dir = tempDir()
        defer { try? FileManager.default.removeItem(at: dir) }
        let s = try GameSession.newGame(resources: res)
        s.world.recordLog = false
        s.runToChaosLoad()
        for _ in 0..<oldTicks(1100) { s.tick() }
        s.world.savesDir = dir
        #expect(s.world.level == newGameSave.level && s.world.currentCamera == newGameSave.camera)
        let url = try #require(s.world.saveNative(slot: 2))
        let data = try fileBytes(url)
        let (ents, _, _) = try Im1.entries(data)
        for e in ents { #expect(sha(e.data) == newGameSave.files[e.name], "\(e.name)") }
        #expect(ents.count == newGameSave.files.count)
        #expect(sha(data) == newGameSave.im1)
        #expect(s.world.warnings.filter { $0.hasPrefix("save") }.isEmpty)
    }
